#include <string.h>

int main(void) {
    int N, M, K;
    if (scanf("%d %d %d", &N, &M, &K) != 3) return 0;

    char password[505];
    scanf("%s", password);

    int counts[505][26] = {{0}};
    int pos = 0;

    for (int i = 0; i < N; ++i) {
        if (password[i] == '#') {
            char word[30];
            scanf("%s", word);
            for (int j = 0; j < K; ++j)
                counts[pos][word[j] - 'a']++;
            pos++;
        }
    }

    long long P;
    scanf("%lld", &P);

    long long suffix[505];
    suffix[M] = 1;
    for (int i = M - 1; i >= 0; --i) {
        long long value = suffix[i + 1] * K;
        suffix[i] = value > P ? P : value;
    }

    long long rank = P;
    int variable = 0;

    for (int i = 0; i < N; ++i) {
        if (password[i] != '#') continue;

        for (int c = 0; c < 26; ++c) {
            int frequency = counts[variable][c];
            if (frequency == 0) continue;

            long long branch = (long long)frequency * suffix[variable + 1];
            if (branch > P) branch = P;

            if (rank > branch) {
                rank -= branch;
            } else {
                password[i] = (char)('a' + c);
                rank = (rank - 1) / frequency + 1;
                break;
            }
        }
        variable++;
    }

    puts(password);
    return 0;
}
