        for (int j = 0; j < K; j++)
            freq[i][word[j] - 'a']++;
    }

    long long P;
    scanf("%lld", &P);

    const long long CAP = 1000000001LL;
    int hashIndex = 0;
    int remaining = M;

    for (int i = 0; i < N; i++) {
        if (password[i] != '#') continue;

        long long suffixCount = 1;
        for (int j = 0; j < remaining - 1; j++) {
            suffixCount *= K;
